import json, pickle, sys
sys.path.insert(0, '/workspace/tmp')
from refmodel import lpm, mask, py_validate

d = pickle.load(open('/workspace/tmp/fail_ans.pkl','rb'))
ops = d['req']['cases'][0]['ops']
exp = d['exp']; got = d['got']
idx = next(i for i,(e,g) in enumerate(zip(exp,got)) if e != g)
print('first mismatch idx', idx, 'exp', exp[idx], 'got', got[idx])
live = {}
loaded = {}
saved = {}
ai = 0
for oi, op in enumerate(ops):
    if op[0] == 'put':
        a = int(op[1],16); ln = op[2]; hop = op[3]
        live[(ln, mask(a, ln))] = hop
    elif op[0] in ('query','image_query'):
        for a_hex in op[1]:
            a = int(a_hex, 16)
            if ai == idx:
                print('op', oi, op[0], 'addr', a_hex, 'state: loaded routes', len(loaded))
                src = live if op[0] == 'query' else loaded
                for (ln, ma), hop in sorted(src.items()):
                    if mask(a, ln) == ma:
                        print('  cand len', ln, 'hop', hop)
                print('  ref lpm:', lpm(src, a), ' program:', got[idx])
            ai += 1
    elif op[0] == 'save':
        saved = dict(live)
    elif op[0] == 'load_saved':
        loaded = dict(saved)
    elif op[0] == 'load':
        ok, r = py_validate(op[1])
        print('op', oi, 'load image valid:', ok, 'routes:', len(r) if r else None)
        if r is not None:
            loaded = r
print('mismatch total:', sum(1 for e,g in zip(exp,got) if e!=g), 'of', len(exp))
EOF
